from rest_framework import serializers
from .models import Order

class OrderCreateSerializer(serializers.ModelSerializer):
    class Meta:
        model = Order
        fields = ["total"]

    def validate(self, attrs):
        if attrs["total"] > 10_000:
            raise serializers.ValidationError("Orders over 10,000 need manual approval.")
        return attrs

# in a view
s = OrderCreateSerializer(data={"total": "-5"})
s.is_valid()        # False
print(s.errors)     # {'total': ['Ensure this value is greater than or equal to 0.'] ...}

from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from rest_framework.routers import DefaultRouter

class OrderViewSet(viewsets.ModelViewSet):
    serializer_class = OrderSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return Order.objects.filter(customer=self.request.user).select_related("customer")

    def perform_create(self, serializer):
        serializer.save(customer=self.request.user)

    @action(detail=True, methods=["post"])
    def cancel(self, request, pk=None):
        order = self.get_object()
        order.status = "cancelled"
        order.save(update_fields=["status"])
        return Response({"status": order.status})

router = DefaultRouter()
router.register("orders", OrderViewSet, basename="order")
urlpatterns = router.urls
